/**
 * Handle file outcomes before format conversion.
 *
 * Reads entry.metadata.file_outcomes (set by Attach metadata and prune).
 * Patches entry.text with a notice for the receiving system.
 * Emits a notification payload on output 2 back to the original sender.
 *
 * Runs BEFORE Bridge entry to client so the text patch is picked up
 * by both adapters regardless of their field naming (text vs content).
 *
 * Output 1: msg continues (always)
 * Output 2: notification payload (only when file outcomes exist)
 */
const entry    = msg.entry;
const outcomes = entry && entry.metadata && entry.metadata.file_outcomes;

if (!outcomes) return [msg, null];

const skipped = [
    ...outcomes.reasons.non_transferable,
    ...outcomes.reasons.oversized,
    ...outcomes.reasons.download_failed
];

if (skipped.length === 0) return [msg, null];

const total   = outcomes.total;
const notice  = " [" + skipped.length + "/" + total
              + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering for manglende vedlegg]";

entry.text = (entry.text || "") + notice;

const has_non_transferable = outcomes.reasons.non_transferable.length > 0;
const has_oversized        = outcomes.reasons.oversized.length > 0;

let type = "upload_failed";
if (has_non_transferable && !has_oversized) type = "non_transferable";
else if (has_oversized && !has_non_transferable) type = "oversized_files";

const notification = {
    payload: {
        type,
        entry_id:     entry.id,
        file_names:   skipped,
        file_count:   skipped.length,
        total_files:  total,
        succeeded:    outcomes.transferred,
        entry_author: entry.author,
        metadata:     entry.metadata
    }
};

return [msg, notification];
